# sequence-match guard asserts the two indexings point at the same protein.
export BINDING_CHAIN="B"

# Stage 2 chain layout for 5d5u.cif
# (verify with: python stage2_redock/stage2_redock.py --ref structures/source_chains/5d5u_chains/5d5u.cif --inspect-only)
